import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"El Diccionario de Terminología","description":"","frontmatter":{},"headers":[],"relativePath":"es/0090-术语词典.md","filePath":"es/0090-术语词典.md"}'),d={name:"es/0090-术语词典.md"};function n(r,e,s,l,c,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="el-diccionario-de-terminologia" tabindex="-1">El Diccionario de Terminología <a class="header-anchor" href="#el-diccionario-de-terminologia" aria-label="Permalink to &quot;El Diccionario de Terminología&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>90</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>diccionario de terminología, conceptos centrales, definiciones, terminología unificada, Universo Hengyuan</td></tr></tbody></table><h2 id="i-notas-sobre-la-terminologia" tabindex="-1">I. Notas sobre la Terminología <a class="header-anchor" href="#i-notas-sobre-la-terminologia" aria-label="Permalink to &quot;I. Notas sobre la Terminología&quot;">​</a></h2><p>Este diccionario recoge los términos centrales del sistema de ambientación de la Civilización Simbiótica del Ancla, con el objetivo de unificar el uso de los términos en todos los documentos y garantizar la coherencia y precisión de la expresión conceptual. Todos los términos están ordenados según la primera letra de su pinyin chino; cada entrada contiene el nombre del término, el nombre de referencia en inglés (si lo hay), la definición y una breve explicación. Este diccionario es un documento de actualización dinámica; a medida que el sistema de ambientación se expande, se añadirán continuamente nuevos términos.</p><h2 id="ii-la-tabla-de-terminos-centrales" tabindex="-1">II. La Tabla de Términos Centrales <a class="header-anchor" href="#ii-la-tabla-de-terminos-centrales" aria-label="Permalink to &quot;II. La Tabla de Términos Centrales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Término</th><th>Definición y explicación</th></tr></thead><tbody><tr><td>1</td><td>Ancla</td><td>Un nodo estable en la red de leyes, que sirve como referencia de coordenadas para mantener la estabilidad de las leyes de los planos, realizar la conexión transplanar y la regresión temporal. En esencia, un Ancla es una condensación de alta densidad de las leyes originarias del universo en una ubicación espacial específica, que posee la capacidad de automantenimiento y calibración.</td></tr><tr><td>2</td><td>Civilización Simbiótica del Ancla</td><td>Una forma de civilización basada en el mecanismo del Ancla como base tecnológica y en la evolución simbiótica como concepto central. Se opone al sistema de cultivo depredador y aboga por devolver el derecho a elegir el destino y la evolución a todos los seres vivos, logrando: más trabajo, más ganancia; crecimiento autónomo; un camino para cada uno; el avance común de las Diez Mil Razas.</td></tr><tr><td>3</td><td>Universo Hengyuan</td><td>La abreviatura del &quot;Universo Original Wanling Hengmao&quot;, el dominio cósmico completo donde la Civilización Simbiótica del Ancla habita y gobierna. Es un ser compuesto constituido por cuatro niveles: los planos materiales, la capa de energía, el dominio de la conciencia y la red de leyes.</td></tr><tr><td>4</td><td>Universo Original Wanling Hengmao</td><td>El nombre completo del Universo Hengyuan. &quot;Wanling&quot; (Diez Mil Espíritus) se refiere a todas las formas de vida que poseen potencial de percepción y evolución; &quot;Hengmao&quot; (Anclas de Equilibrio) se refiere al mecanismo del Ancla que mantiene el equilibrio cósmico; &quot;Universo Original&quot; enfatiza los atributos esenciales de tomar las leyes originarias como fundamento y la evolución simbiótica como dirección.</td></tr><tr><td>5</td><td>Simbiosis</td><td>Uno de los conceptos centrales de la Civilización Simbiótica del Ancla, que se refiere a la evolución común de individuos, razas y civilizaciones diferentes mediante la cooperación mutuamente beneficiosa, en lugar de la evolución depredadora a costa de otros.</td></tr><tr><td>6</td><td>Sistema de Cultivo Depredador</td><td>Un método de cultivo que logra la autoevolución devorando la energía, la fortuna e incluso el origen de los débiles. Es el tipo de sistema que la Civilización Simbiótica del Ancla rechaza firmemente, considerado la causa raíz de la aceleración del aumento de la entropía cósmica y la frecuencia de las discontinuidades civilizacionales.</td></tr><tr><td>7</td><td>Los Trescientos Sistemas de Cultivo de Origen</td><td>Caminos de cultivo ortodoxos extraídos directamente de las leyes originarias del universo y verificados por las Anclas, trescientos en total, divididos en seis grandes categorías: deducción de origen, ciclo de vida, principios legales espaciales, ascensión de la conciencia, red simbiótica e ingeniería aplicada, con cincuenta sistemas en cada categoría.</td></tr><tr><td>8</td><td>Las Tres Bases de Origen</td><td>Los tres primeros sistemas fundamentales entre los trescientos sistemas — el Sistema de Iteración por Deducción (n.º 1), el Sistema de Ciclo de Vida (n.º 2) y el Sistema de Despacho de Principios Legales Espaciales (n.º 3) — la base de cultivo de todos los demás sistemas.</td></tr><tr><td>9</td><td>Sistema de Iteración por Deducción</td><td>El sistema de cultivo de origen n.º 1, caracterizado por una amplificación centuplicada de la deducción de cultivo, que utiliza la aplicación técnica del Fruto Multiplicador para aumentar la capacidad de deducción cien veces, enfatizando la optimización de los caminos de cultivo mediante la deducción, la verificación y la iteración.</td></tr><tr><td>10</td><td>Sistema de Ciclo de Vida</td><td>El sistema de cultivo de origen n.º 2, centrado en el ciclo virtuoso de la energía vital, enfatizando que el intercambio de energía entre el cultivador y el entorno debe ser cíclico, no depredador.</td></tr><tr><td>11</td><td>Sistema de Despacho de Principios Legales Espaciales</td><td>El sistema de cultivo de origen n.º 3, centrado en la comprensión y el despacho de las leyes espaciales, la base de cultivo de aplicaciones importantes como la interacción transplanar, la construcción de espacios aislados y la tecnología del Espejo de Réplica.</td></tr><tr><td>12</td><td>Fruto Multiplicador</td><td>El Fruto Multiplicador originario del mundo de One Piece, aplicado técnicamente en el Universo Hengyuan, capaz de aumentar cien veces la capacidad de deducción del cultivador, la herramienta auxiliar central del Sistema de Iteración por Deducción. Uno de los impulsos iniciales.</td></tr><tr><td>13</td><td>Mecanismo de Contrato Vinculado a la Producción</td><td>El mecanismo de distribución de recursos de la Civilización Simbiótica del Ancla, que distribuye los recursos de cultivo cósmico a individuos o grupos en forma de &quot;contrato&quot;; los contratistas obtienen el derecho de uso de los recursos mediante el trabajo y la contribución, logrando más trabajo, más ganancia.</td></tr><tr><td>14</td><td>Estrategia de Activación del 20 %</td><td>El objetivo estratégico por fases de la Civilización Simbiótica del Ancla: activar en la fase inicial al 20 % de los seres vivos del universo para que se conviertan en Potencias Supremas de los Planos, utilizándolos como columna vertebral para impulsar la evolución común del 80 % restante de los seres vivos.</td></tr><tr><td>15</td><td>Potencia Suprema del Plano</td><td>Un poderoso que ha cultivado hasta un nivel extremadamente alto y puede mantener de manera independiente la estabilidad de las leyes de un plano. Es el objetivo de la Estrategia de Activación del 20 % y una fuerza importante de mantenimiento de la red del Ancla.</td></tr><tr><td>16</td><td>Red de Leyes</td><td>El cuarto nivel de la estructura del Universo Hengyuan, el fundamento operativo de las leyes originarias del universo y la base raíz de las Anclas. La red de leyes atraviesa todo el universo y es la base técnica de todas las operaciones de leyes (incluidos el despacho espacial, la regresión temporal y la transformación de energía).</td></tr><tr><td>17</td><td>Plano</td><td>Una región de existencia definida por un conjunto relativamente estable de leyes, que posee continuidad espacio-temporal independiente. Cada plano tiene constantes físicas, densidad de energía, velocidad de flujo del tiempo y nivel de actividad de la conciencia únicos.</td></tr><tr><td>18</td><td>Barrera de Leyes</td><td>La barrera de leyes que separa planos adyacentes, cuya fuerza depende del grado de diferencia entre los parámetros de leyes de los planos adyacentes. La travesía transplanar requiere superar las barreras de leyes.</td></tr><tr><td>19</td><td>Huella de Leyes</td><td>Un identificador único generado por operación de hash sobre los parámetros de leyes centrales de cada plano, de 128 bits de longitud, uno de los parámetros centrales del sistema de coordenadas de planos.</td></tr><tr><td>20</td><td>Observar Primero, Luego Intervenir Dentro de Límites</td><td>El principio operativo primordial de la regresión temporal y la arqueología transplanar, que exige que toda regresión o arqueología complete primero la fase de observación pura y, tras confirmar la ausencia de riesgos mayores, solo realice una intervención limitada.</td></tr><tr><td>21</td><td>Espejo de Réplica</td><td>Un dispositivo de réplica de alta precisión basado en las leyes de los principios legales espaciales, capaz de realizar una réplica completa 1:1 de la zona objetivo sin tocar el original, el equipo central del esquema de arqueología fuera de sitio.</td></tr><tr><td>22</td><td>Espacio Aislado</td><td>Una región de leyes independiente construida mediante la tecnología de despacho de principios legales espaciales, utilizada para portar las copias arqueológicas y servir como lugar de trabajo del personal arqueológico, completamente separado del universo externo por barreras de leyes.</td></tr><tr><td>23</td><td>Retorno de Solo Conocimiento</td><td>El principio central del protocolo arqueológico, que significa que durante el proceso arqueológico solo pueden obtenerse del objeto objetivo conocimientos e información abstractos; no puede retornarse ningún material, energía o ser vivo.</td></tr><tr><td>24</td><td>Purificación de la Información</td><td>El proceso técnico de desprender por completo las huellas de leyes del plano de origen contenidas en la información bruta y conservar solo el contenido semántico puro, el eslabón clave para garantizar la seguridad del conocimiento retornado.</td></tr><tr><td>25</td><td>Paradoja Temporal</td><td>El fenómeno por el cual la lógica causal se vuelve autocontradictoria debido a un comportamiento de interferencia durante las operaciones de regresión temporal, incluidas las cuatro grandes categorías: paradoja del parricidio, paradoja informativa, paradoja ontológica y paradoja de eventos.</td></tr><tr><td>26</td><td>Cadena Causal</td><td>La estructura lineal continua de causas y consecuencias entre los eventos, un concepto central de las leyes del tiempo. El riesgo central de las operaciones de regresión temporal es la perturbación de la cadena causal.</td></tr><tr><td>27</td><td>Constitución Simbiótica</td><td>La ley fundamental de la Civilización Simbiótica del Ancla, con la más alta fuerza jurídica, que establece el fundamento civilizacional de oponerse a la depredación y promover la simbiosis, así como los siete principios constitucionales básicos.</td></tr><tr><td>28</td><td>Igualdad de las Diez Mil Razas</td><td>Uno de los siete principios básicos de la Constitución Simbiótica, que significa que todas las formas de vida, sin importar su raza, nivel de cultivo u origen, son iguales ante la ley.</td></tr><tr><td>29</td><td>Vida Anómala</td><td>Formas de vida que no se ajustan a la definición convencional de vida y poseen formas de existencia especiales, que requieren identificación y gestión según los procedimientos de tratamiento estandarizados de tres categorías.</td></tr><tr><td>30</td><td>Energía Anómala</td><td>Formas de energía que no se ajustan a la clasificación convencional de energía y poseen atributos y patrones de comportamiento especiales, que requieren clasificación y control según los procedimientos de tratamiento estandarizados de tres categorías.</td></tr><tr><td>31</td><td>Entidad Oscura de Reemplazo</td><td>Una forma de vida especial que involucra la cuestión ética de la coexistencia de dos almas, que requiere gestión según las Directrices Éticas del Alma Dual y las reglas de tratamiento de las cuatro ramas.</td></tr><tr><td>32</td><td>Directrices Éticas del Alma Dual</td><td>Directrices éticas para el estado de coexistencia de dos almas dentro de una Entidad Oscura de Reemplazo, cuyo núcleo es el respeto de los derechos respectivos de las dos almas y la prohibición de la fusión forzada o la eliminación de una de las partes.</td></tr><tr><td>33</td><td>Los Cinco Tipos de Civilización Simbiótica</td><td>Cinco tipos de sociedades simbióticas divididas según las características de las civilizaciones del mundo real: el tipo intensivo de Asia Oriental, el tipo de bienestar nórdico, el tipo pluralista norteamericano, el tipo social de Europa continental y el tipo de desarrollo que alcanza.</td></tr><tr><td>34</td><td>La Vía de Ascensión en Cuatro Etapas</td><td>La ruta en cuatro etapas para la ascensión global del Universo Hengyuan: construcción de la base real → potenciación tecnológica → evolución de la conciencia → simbiosis interestelar.</td></tr><tr><td>35</td><td>La Realidad como Fundamento</td><td>Una de las posiciones fundamentales de la Civilización Simbiótica del Ancla, que significa que el mundo real es el único mundo real, que los mundos novelescos son experimentos mentales falsos, que la ficción se complementa con la realidad cuando es insuficiente, y que lo que la realidad no posee se crea mediante la ascensión basada en las leyes.</td></tr><tr><td>36</td><td>Índice de Simbiosis</td><td>Un indicador cuantitativo que evalúa el grado de integración de una civilización o individuo con la red simbiótica, que cubre múltiples dimensiones como el grado de compartición de recursos, la frecuencia de colaboración y la proporción de comportamiento altruista.</td></tr><tr><td>37</td><td>Asamblea Legislativa del Ancla</td><td>El órgano supremo de poder de la Civilización Simbiótica del Ancla, compuesto por representantes de las Diez Mil Razas en proporción, que ejerce el poder legislativo y el poder de decisión de asuntos mayores.</td></tr><tr><td>38</td><td>Comité Ejecutivo Simbiótico</td><td>El órgano administrativo supremo de la Civilización Simbiótica del Ancla, responsable de la ejecución de la constitución y las leyes y de la gobernanza cotidiana.</td></tr><tr><td>39</td><td>Tribunal Simbiótico</td><td>El órgano judicial supremo de la Civilización Simbiótica del Ancla, que ejerce de manera independiente el poder judicial, responsable del control de constitucionalidad y el juzgamiento de casos mayores.</td></tr><tr><td>40</td><td>Administración de Planos</td><td>Un órgano especializado bajo la Asamblea Legislativa del Ancla, responsable del mantenimiento de la base maestra de coordenadas de planos, la aprobación de permisos de travesía y la gestión de la arqueología transplanar.</td></tr></tbody></table><h2 id="iii-normas-de-uso-de-la-terminologia" tabindex="-1">III. Normas de Uso de la Terminología <a class="header-anchor" href="#iii-normas-de-uso-de-la-terminologia" aria-label="Permalink to &quot;III. Normas de Uso de la Terminología&quot;">​</a></h2><ol><li>Los términos recogidos en este diccionario son términos estándar; todos los documentos deben dar prioridad a las expresiones estándar de este diccionario.</li><li>El mismo concepto debe usar el mismo término en diferentes documentos; no deben sustituirse arbitrariamente sinónimos.</li><li>Los nuevos términos generados en nuevas ambientaciones deben presentarse oportunamente al Comité de Terminología para su revisión, y añadirse a este diccionario tras su aprobación.</li><li>Si se revisa la definición de un término, prevalece la versión más reciente de este diccionario, y el contenido de la revisión también debe registrarse en las notas de versión del documento.</li><li>Al citar un término, puede usarse el nombre completo en su primera aparición y la abreviatura posteriormente, pero debe garantizarse la claridad del significado en el contexto.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El diccionario de terminología es la piedra angular lingüística de todo el sistema de ambientación. El sistema terminológico unificado garantiza la coherencia conceptual entre los cien documentos, permitiendo a los lectores cambiar sin problemas entre los diferentes módulos sin ambigüedad de comprensión. A medida que el sistema de ambientación se enriquece y perfecciona, este diccionario se actualizará continuamente, sirviendo siempre como la fuente terminológica autorizada de todos los documentos.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Panorama del Cosmos)</li><li>02-锚点本源定义与本质 (Definición y Esencia del Origen del Ancla)</li><li>99-文档版本与维护说明 (Notas de Versión y Mantenimiento de Documentos)</li></ul>',12)])])}const g=a(d,[["render",n]]);export{p as __pageData,g as default};
